import React, { useState, useEffect } from "react";

function App() {
  const [darkMode, setDarkMode] = useState(false);
  const [ingredients, setIngredients] = useState("");
  const [mealType, setMealType] = useState("Breakfast");
  const [cuisine, setCuisine] = useState("");
  const [cookingTime, setCookingTime] = useState("Less than 30 minutes");
  const [complexity, setComplexity] = useState("Beginner");
  const [recipeText, setRecipeText] = useState("");
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    document.documentElement.classList.toggle("dark", darkMode);
  }, [darkMode]);

  const handleSubmit = async () => {
    setLoading(true);
    try {
      const res = await fetch("http://localhost:5007/api/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ingredients,
          mealType,
          cuisine,
          cookingTime,
          complexity,
        }),
      });

      const data = await res.json();

      if (res.ok) {
        setRecipeText(data.recipe || "No recipe received.");
        setError(null);
      } else {
        setRecipeText("");
        setError(data.error || "Failed to generate recipe.");
      }
    } catch (err) {
      console.error("Error generating recipe:", err);
      setError("Failed to generate recipe. Please try again.");
    }
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-white to-gray-100 dark:from-gray-900 dark:to-gray-800 flex items-center justify-center p-4 transition-colors duration-300">
      {/* Dark Mode Toggle */}
      <div className="absolute top-4 right-4">
        <button
          onClick={() => setDarkMode(!darkMode)}
          className="bg-gray-800 dark:bg-white text-white dark:text-black px-4 py-2 rounded shadow hover:opacity-80"
        >
          {darkMode ? "☀️" : "🌙"}
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-6xl">
        {/* LEFT - Form */}
        <div className="bg-white dark:bg-gray-700 dark:text-white rounded-xl shadow-md p-6">
          <h2 className="text-xl font-bold text-center mb-6">
            Recipe Generator
          </h2>

          {/* Text Inputs */}
          {[
            {
              label: "Ingredients",
              value: ingredients,
              onChange: setIngredients,
              placeholder: "e.g. tomato, potato, onion",
            },
            {
              label: "Cuisine Preference",
              value: cuisine,
              onChange: setCuisine,
              placeholder: "e.g. Italian, Mexican",
            },
          ].map((field, index) => (
            <div className="mb-4" key={index}>
              <label className="block font-semibold mb-1">{field.label}</label>
              <input
                type="text"
                value={field.value}
                onChange={(e) => field.onChange(e.target.value)}
                placeholder={field.placeholder}
                className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              />
            </div>
          ))}

          {/* Dropdown Inputs */}
          {[
            {
              label: "Meal Type",
              value: mealType,
              onChange: setMealType,
              options: ["Breakfast", "Lunch", "Dinner", "Snack"],
            },
            {
              label: "Cooking Time",
              value: cookingTime,
              onChange: setCookingTime,
              options: [
                "Less than 30 minutes",
                "30-60 minutes",
                "More than 1 hour",
              ],
            },
            {
              label: "Complexity",
              value: complexity,
              onChange: setComplexity,
              options: ["Beginner", "Intermediate", "Advanced"],
            },
          ].map((dropdown, index) => (
            <div className="mb-4" key={index}>
              <label className="block font-semibold mb-1">
                {dropdown.label}
              </label>
              <select
                value={dropdown.value}
                onChange={(e) => dropdown.onChange(e.target.value)}
                className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              >
                {dropdown.options.map((opt, i) => (
                  <option key={i}>{opt}</option>
                ))}
              </select>
            </div>
          ))}

          {/* Generate Button */}
          <button
            onClick={handleSubmit}
            className="bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded w-full"
          >
            Generate Recipe
          </button>

          {/* Clear Results Button */}
          {recipeText && !loading && (
            <button
              onClick={() => setRecipeText("")}
              className="mt-3 text-sm underline text-gray-600 dark:text-gray-300 hover:text-blue-500"
            >
              Clear Results
            </button>
          )}
        </div>

        {/* RIGHT - Recipe Output */}
        <div className="bg-white dark:bg-gray-700 dark:text-white rounded-xl shadow-md p-6 overflow-auto whitespace-pre-wrap">
          <h2 className="text-xl font-bold mb-4 text-center">Recipe Output</h2>

          {loading ? (
            <div className="flex items-center justify-center h-full">
              <div className="relative w-12 h-12">
                <div className="absolute inset-0 rounded-full border-4 border-blue-400 border-t-transparent animate-spin"></div>
              </div>
            </div>
          ) : error ? (
            <p className="text-red-500 text-center">{error}</p>
          ) : recipeText ? (
            <div className="text-gray-800 dark:text-gray-200 text-sm leading-relaxed">
              {recipeText}
              <button
                onClick={() => navigator.clipboard.writeText(recipeText)}
                className="text-xs text-blue-500 hover:underline block mt-4"
              >
                📋 Copy Recipe
              </button>
            </div>
          ) : (
            <p className="text-gray-500 dark:text-gray-300 text-center">
              No recipe yet. Fill out the form and click "Generate Recipe".
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

export default App;
